if mibBuilder.loadTexts: cippfIpProfileEntry.setStatus('current')
if mibBuilder.loadTexts: cippfIpProfileEntry.setDescription('Each entry defines the type, state, and the last\n                object index assigned to a filter of the filter\n                profile.')
